// Generated by Maria Network Monitor; schema=1
// Local HA resource. No remote dependencies, credentials, or network telemetry.
const groups = {printer: "printers", computer: "computers", camera: "cameras",
  access_point: "access_points", server: "servers", voip: "voip", unknown: "unknown"};
const icons = {printer: "mdi:printer", computer: "mdi:desktop-classic", camera: "mdi:cctv",
  access_point: "mdi:access-point", server: "mdi:server", voip: "mdi:phone", unknown: "mdi:devices"};
const format = value => value == null ? "—" : typeof value === "number"
  ? value.toLocaleString("ru-RU") : String(value);
const statusText = value => ({idle: "Готов", processing: "Печатает", stopped: "Остановлен",
  3: "Готов", 4: "Печатает", 5: "Остановлен"}[String(value)] || format(value));
const style = `
 :host {display:block; color:var(--primary-text-color); font-family:var(--paper-font-body1_-_font-family, sans-serif)}
 * {box-sizing:border-box} ha-card {display:block; padding:18px; border-radius:var(--ha-card-border-radius,12px)}
 h2,h3,p {margin:0} h2 {font-size:20px; font-weight:600} h3 {font-size:15px; font-weight:600}
 .heading {display:flex; align-items:center; gap:9px; margin:0 0 14px}
 .overview,.printer-grid {display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,300px),1fr));gap:14px}
 ha-icon {--mdc-icon-size:21px;flex:none} .sub,.small {color:var(--secondary-text-color);font-size:12px;line-height:1.5}
 .sub {margin:7px 0 14px} .stack {display:grid;gap:12px} .tiles {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
 .tile {border:1px solid var(--divider-color,#ddd);border-radius:12px;padding:11px;display:flex;gap:9px;align-items:center;min-width:0}
 .tile button {all:unset;cursor:pointer;min-width:0;flex:1} .tile button:focus-visible {outline:2px solid var(--primary-color)}
 .tile strong {display:block;font-size:13px;overflow-wrap:anywhere} .tile .small {display:block}
 .badge {border-radius:50%;padding:8px;display:flex;background:var(--secondary-background-color);color:var(--secondary-text-color)}
 .online .badge {color:var(--primary-color,#00897b);background:color-mix(in srgb,var(--primary-color,#00897b) 14%,transparent)}
 .offline {border-left:4px solid var(--error-color,#db4437)} .offline .badge {color:var(--error-color,#db4437)}
 .warning {border-left:4px solid var(--warning-color,#e6a000)} .stale {border-left:4px solid var(--disabled-text-color,#888)}
 .metrics {display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:14px}
 .metric {border-radius:10px;padding:10px;background:var(--secondary-background-color)} .metric b {display:block;font-size:23px;line-height:1.4}
 .router {display:flex;gap:7px;align-items:center;margin-top:8px;font-size:13px}
 .ok {color:var(--primary-color,#00897b)} .bad {color:var(--error-color,#db4437)} .warn {color:var(--warning-color,#e6a000)}
 .printer {border:1px solid var(--divider-color,#ddd);border-radius:12px;padding:14px;min-width:0}
 .printer.offline {border-left:4px solid var(--error-color,#db4437)}
 .printer.warning {border-left:4px solid var(--warning-color,#e6a000)}
 .printer.stale {border-left:4px solid var(--disabled-text-color,#888)}
 .printer header {display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}
 .printer .tiles {margin:10px 0} .supplies {display:grid;gap:10px;margin:14px 0}
 .supply-label {display:flex;justify-content:space-between;gap:10px;font-size:13px;margin-bottom:5px;overflow-wrap:anywhere}
 .track {height:6px;border-radius:6px;background:var(--divider-color,#ddd);overflow:hidden}
 .fill {height:100%;background:var(--primary-color,#00897b);border-radius:6px}.fill.low {background:var(--warning-color,#e6a000)}
 .details {display:grid;gap:7px;font-size:13px}.row {display:flex;justify-content:space-between;gap:12px}
 .row span:last-child {text-align:right;overflow-wrap:anywhere} .notice {font-size:12px;line-height:1.5;margin-top:9px;color:var(--secondary-text-color)}
 a {display:inline-block;margin-top:13px;color:var(--primary-color);text-decoration:none;font-size:13px;padding:3px 0}
 .empty {font-size:13px;color:var(--secondary-text-color);padding:5px 0} .alert {font-size:12px;margin:7px 0;color:var(--warning-color,#e6a000)}
 @media(max-width:360px) {.tiles {grid-template-columns:1fr}.metrics {gap:5px}.metric {padding:7px}.metric b {font-size:20px}}
`;

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text != null) node.textContent = text;
  if (className) node.className = className;
  return node;
}
function icon(name) {
  const node = element("ha-icon");
  node.setAttribute("icon", name);
  return node;
}
export function inventories(hass) {
  return Object.values(hass.states || {}).filter(state =>
    state.attributes?.maria_role === "site_inventory" && state.attributes.schema === 1)
    .map(state => ({...state.attributes, monitor_available: !["unavailable", "unknown"].includes(state.state)}))
    .sort((a, b) => a.name.localeCompare(b.name, "ru"));
}
export function devicesFor(site, group) {
  return (site?.devices || []).filter(device => (groups[device.type] || "unknown") === group)
    .sort((a, b) => Number(b.online === false) - Number(a.online === false) ||
      Number(!!b.printer?.problem) - Number(!!a.printer?.problem) || a.name.localeCompare(b.name, "ru"));
}

class MariaNetworkCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({mode: "open"});
  }
  setConfig(config) {
    if (!["overview", "summary", "group"].includes(config.mode)) throw Error("Maria: invalid card mode");
    if (config.mode !== "overview" && !config.site_id) throw Error("Maria: site_id required");
    this.config = {...config};
    this.fingerprint = null;
    if (this._hass) this.render();
  }
  set hass(hass) {
    this._hass = hass;
    if (!this.config) return;
    const all = inventories(hass);
    const relevant = this.config.mode === "overview" ? all : all.filter(site => site.site_id === this.config.site_id);
    const signature = JSON.stringify(relevant);
    if (signature !== this.fingerprint) {
      this.fingerprint = signature;
      this.render(relevant);
    }
  }
  getCardSize() { return this.config?.mode === "summary" ? 3 : 6; }
  getGridOptions() { return {columns: "full", rows: "auto"}; }
  async moreInfo(uniqueId) {
    // Resolve actual registry entity_id; never guess it from a DHCP name.
    try {
      const registry = await this._hass.callWS({type: "config/entity_registry/list"});
      const entry = registry.find(item => item.platform === "mqtt" && item.unique_id === uniqueId);
      if (entry && this.isConnected) this.dispatchEvent(new CustomEvent("hass-more-info", {
        bubbles: true, composed: true, detail: {entityId: entry.entity_id},
      }));
    } catch (error) {
      console.warn("Maria: entity history is not accessible", error);
    }
  }
  tile(name, value, device, uid, image, connection = false) {
    const unknown = this.currentStale;
    const stateClass = connection ? unknown ? "stale" : device.online ? "online" : "offline" : "";
    const tile = element("div", null, "tile " + stateClass);
    const badge = element("span", null, "badge"); badge.append(icon(image)); tile.append(badge);
    const button = element("button"); button.type = "button";
    button.append(element("strong", name), element("span", value, "small"));
    button.setAttribute("aria-label", name + ": " + value + ". История");
    button.addEventListener("click", () => this.moreInfo(uid)); tile.append(button);
    return tile;
  }
  summary(site, navigate) {
    const stale = site.stale || !site.monitor_available;
    const card = element("ha-card", null, stale ? "stale" : !site.router_online ? "offline" : site.printer_problems ? "warning" : "");
    card.append(element("h2", site.name));
    const router = element("div", null, "router " + (!site.monitor_available ? "warn" : site.router_online ? "ok" : "bad"));
    router.append(icon("mdi:router-network"), element("span", !site.monitor_available ? "Монитор недоступен" :
      site.router_online ? "MikroTik · API доступен" : "MikroTik · API недоступен")); card.append(router);
    const metrics = element("div", null, "metrics");
    for (const [label, key] of [["На связи", "online"], ["Офлайн", "offline"], ["Проблемных принтеров", "printer_problems"]]) {
      const metric = element("div", null, "metric");
      metric.append(element("b", stale ? "—" : format(site[key])), element("span", label, "small")); metrics.append(metric);
    }
    card.append(metrics);
    if (stale) card.append(element("p", "Нет актуального опроса. Сохранено устройств: " + format(site.total) + ".", "notice"));
    else card.append(element("p", "Устройств: " + format(site.total), "notice"));
    if (site.last_success_at) card.append(element("p", "Последний опрос: " + new Date(site.last_success_at).toLocaleString("ru-RU"), "notice"));
    if (navigate) {
      const link = element("a", "Открыть оборудование →");
      // Relative view URL keeps dashboard independent of the HA host/path.
      const base = window.location.pathname.split("/").filter(Boolean)[0];
      link.href = "/" + base + "/" + encodeURIComponent(site.site_id); card.append(link);
    }
    return card;
  }
  printer(device) {
    const data = device.printer || {};
    const card = element("article", null, "printer " + (this.currentStale ? "stale" : !device.online ? "offline" : data.problem ? "warning" : ""));
    const header = element("header");
    const heading = element("div", null, "heading"); heading.append(icon("mdi:printer"), element("h3", device.name));
    header.append(heading); card.append(header);
    const tiles = element("div", null, "tiles");
    tiles.append(this.tile("Связь", this.currentStale ? "Нет актуальных данных" : device.online ? "На связи" : "Офлайн",
      device, device.online_unique_id, "mdi:lan-connect", true));
    tiles.append(this.tile("Всего страниц", format(data.page_count), device, device.id + "_page_count", "mdi:counter")); card.append(tiles);
    const supplies = element("div", null, "supplies");
    for (const supply of data.supplies || []) {
      const row = element("div");
      const label = element("div", null, "supply-label");
      label.append(element("span", supply.name), element("strong", supply.percent == null ? "Нет данных" :
        format(supply.percent) + "%" + (supply.warning ? " · низкий уровень" : ""), supply.warning ? "warn" : "")); row.append(label);
      if (supply.percent != null) {
        const track = element("div", null, "track");
        const fill = element("div", null, "fill" + (supply.warning ? " low" : ""));
        fill.style.width = Math.max(0, Math.min(100, Number(supply.percent))) + "%";
        track.setAttribute("role", "meter"); track.setAttribute("aria-label", supply.name);
        track.setAttribute("aria-valuemin", "0"); track.setAttribute("aria-valuemax", "100"); track.setAttribute("aria-valuenow", supply.percent);
        track.append(fill); row.append(track);
      }
      if (supply.kind === "waste-toner") row.append(element("div", "Отработка · значение по данным принтера; низкий процент не является предупреждением", "small"));
      supplies.append(row);
    }
    card.append(supplies);
    if (!(data.supplies || []).length) card.append(element("p", "Расходники не сообщаются принтером", "notice"));
    const details = element("div", null, "details");
    for (const [label, value] of [["Состояние печати", statusText(data.status)], ["Очередь", format(data.queue)],
      ["Принимает задания", data.accepting_jobs == null ? "—" : data.accepting_jobs ? "Да" : "Нет"]]) {
      const row = element("div", null, "row"); row.append(element("span", label), element("span", value)); details.append(row);
    }
    card.append(details);
    const reasons = (data.reasons || []).filter(reason => reason !== "none");
    if (reasons.length) card.append(element("p", reasons.join(", "), "alert"));
    if (this.currentStale || !device.online || !data.ipp_fresh || !data.snmp_fresh)
      card.append(element("p", "Часть телеметрии может быть последней известной. IPP: " +
        this.observed(data.ipp_observed_at) + "; SNMP: " + this.observed(data.snmp_observed_at), "notice"));
    card.append(element("p", "История счётчика — по нажатию на «Всего страниц».", "notice"));
    return card;
  }
  observed(time) { return time ? new Date(time * 1000).toLocaleString("ru-RU") : "нет успешного опроса"; }
  render(sites = inventories(this._hass)) {
    const root = this.shadowRoot;
    root.replaceChildren(element("style", style));
    const selected = sites.find(site => site.site_id === this.config.site_id);
    if (this.config.mode === "overview") {
      const stack = element("div", null, "overview");
      for (const site of sites) stack.append(this.summary(site, true));
      if (!sites.length) { const card = element("ha-card"); card.append(element("h2", "Maria Network Monitor"), element("p", "Ожидаем inventory из MQTT. Проверьте работу монитора и MQTT integration.", "notice")); stack.append(card); }
      root.append(stack); return;
    }
    if (!selected) { const card = element("ha-card", "Ожидаем данные филиала из MQTT."); root.append(card); return; }
    if (this.config.mode === "summary") { root.append(this.summary(selected, false)); return; }
    this.currentStale = selected.stale || !selected.monitor_available;
    const card = element("ha-card");
    const heading = element("div", null, "heading"); heading.append(icon(this.config.icon || "mdi:devices"), element("h3", this.config.title)); card.append(heading);
    const devices = devicesFor(selected, this.config.group);
    const container = element("div", null, this.config.group === "printers" ? "printer-grid" : "tiles");
    for (const device of devices) {
      container.append(this.config.group === "printers" ? this.printer(device) :
        this.tile(device.name, this.currentStale ? "Нет актуальных данных" : device.online ? "На связи" : "Офлайн",
          device, device.online_unique_id, icons[device.type] || icons.unknown, true));
    }
    if (!devices.length) container.append(element("p", "Устройств этого типа пока нет", "empty"));
    card.append(container); root.append(card);
  }
}
if (!customElements.get("maria-network-card")) customElements.define("maria-network-card", MariaNetworkCard);
window.customCards = window.customCards || [];
if (!window.customCards.some(card => card.type === "maria-network-card"))
  window.customCards.push({type: "maria-network-card", name: "Maria Network Monitor", description: "Automatic site inventory"});
